using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Text;
using System.ComponentModel.DataAnnotations;
using LankaSaaS.Application;
using LankaSaaS.Domain;
using LankaSaaS.Infrastructure;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;
using System.Threading.RateLimiting;

var builder=WebApplication.CreateBuilder(args);
var jwtKey=builder.Configuration["Jwt:Key"] ?? throw new InvalidOperationException("Jwt:Key is required");
builder.Services.AddHttpContextAccessor(); builder.Services.AddScoped<ITenantContext,HttpTenantContext>();
builder.Services.AddDbContext<AppDbContext>(o=>o.UseNpgsql(builder.Configuration.GetConnectionString("Default")));
builder.Services.AddScoped<IPasswordHasher<User>,PasswordHasher<User>>(); builder.Services.AddScoped<TokenService>();
builder.Services.AddHttpClient();
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new(){ValidateIssuer=true,ValidateAudience=true,ValidateLifetime=true,ValidateIssuerSigningKey=true,ValidIssuer=builder.Configuration["Jwt:Issuer"],ValidAudience=builder.Configuration["Jwt:Audience"],IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtKey)),ClockSkew=TimeSpan.FromSeconds(30)});
builder.Services.AddAuthorization(o=>o.AddPolicy("AdminOnly",p=>p.RequireRole(Roles.Admin))); builder.Services.AddProblemDetails(); builder.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.WithOrigins(builder.Configuration["FrontendUrl"]??"http://localhost:3000").AllowAnyHeader().AllowAnyMethod().AllowCredentials()));
builder.Services.AddRateLimiter(o=>{o.RejectionStatusCode=StatusCodes.Status429TooManyRequests;o.AddPolicy("Auth",context=>RateLimitPartition.GetFixedWindowLimiter(context.Connection.RemoteIpAddress?.ToString()??"unknown",_=>new FixedWindowRateLimiterOptions{PermitLimit=10,Window=TimeSpan.FromMinutes(1),QueueLimit=0,AutoReplenishment=true}));});
var app=builder.Build(); app.UseExceptionHandler(); app.UseCors(); app.UseRateLimiter(); app.UseAuthentication(); app.UseMiddleware<SubscriptionAccessMiddleware>(); app.UseAuthorization();
if(!app.Environment.IsEnvironment("Testing")){using var scope=app.Services.CreateScope();await scope.ServiceProvider.GetRequiredService<AppDbContext>().Database.MigrateAsync();}

var auth=app.MapGroup("/api/auth").AddEndpointFilter<ValidationFilter>();
auth.MapPost("/register",async(RegisterRequest r,HttpContext http,AppDbContext db,IPasswordHasher<User> hasher,TokenService tokens,CancellationToken ct)=>{
 var email=r.Email.Trim().ToLowerInvariant(); if(await db.Users.IgnoreQueryFilters().AnyAsync(x=>x.Email==email,ct)) return Results.Conflict(new{message="An account with this email already exists."});
 await using var tx=await db.Database.BeginTransactionAsync(ct); var tenant=new Tenant{Name=r.BusinessName.Trim(),BusinessName=r.BusinessName.Trim(),Email=email,Phone=r.Phone,Address=r.Address}; db.Tenants.Add(tenant);
 var user=new User{TenantId=tenant.Id,FirstName=r.FirstName.Trim(),LastName=r.LastName.Trim(),Email=email,PasswordHash="",Role=Roles.Admin}; user.PasswordHash=hasher.HashPassword(user,r.Password); db.Users.Add(user); var result=tokens.Create(user); db.RefreshTokens.Add(result.Stored); await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); RefreshCookie.Set(http,result.RawRefreshToken,result.Stored.ExpiresAt,app.Environment); return Results.Created("/api/auth/me",result.Response);
}).AllowAnonymous().RequireRateLimiting("Auth");
auth.MapPost("/login",async(LoginRequest r,HttpContext http,AppDbContext db,IPasswordHasher<User> hasher,TokenService tokens,CancellationToken ct)=>{
 var user=await db.Users.IgnoreQueryFilters().SingleOrDefaultAsync(x=>x.Email==r.Email.Trim().ToLowerInvariant(),ct); if(user is null||!user.IsActive||hasher.VerifyHashedPassword(user,user.PasswordHash,r.Password)==PasswordVerificationResult.Failed) return Results.Unauthorized();var now=DateTimeOffset.UtcNow;user.LoginCount++;user.LastLoginAt=now;db.LoginEvents.Add(new LoginEvent{TenantId=user.TenantId,UserId=user.Id,CreatedAt=now,UpdatedAt=now});await db.LoginEvents.IgnoreQueryFilters().Where(x=>x.TenantId==user.TenantId&&x.CreatedAt<now.AddDays(-90)).ExecuteDeleteAsync(ct);var result=tokens.Create(user); db.RefreshTokens.Add(result.Stored); await db.SaveChangesAsync(ct); RefreshCookie.Set(http,result.RawRefreshToken,result.Stored.ExpiresAt,app.Environment); return Results.Ok(result.Response);
}).AllowAnonymous().RequireRateLimiting("Auth");
auth.MapPost("/refresh",async(HttpContext http,AppDbContext db,TokenService tokens,CancellationToken ct)=>{
 if(!http.Request.Cookies.TryGetValue("refresh_token",out var raw))return Results.Unauthorized();var hash=TokenService.Hash(raw); var old=await db.RefreshTokens.IgnoreQueryFilters().SingleOrDefaultAsync(x=>x.TokenHash==hash,ct); if(old is null||old.RevokedAt!=null||old.ExpiresAt<=DateTimeOffset.UtcNow) return Results.Unauthorized(); var user=await db.Users.IgnoreQueryFilters().SingleOrDefaultAsync(x=>x.Id==old.UserId&&x.IsActive,ct);if(user is null)return Results.Unauthorized();old.RevokedAt=DateTimeOffset.UtcNow; var next=tokens.Create(user); db.RefreshTokens.Add(next.Stored); await db.SaveChangesAsync(ct);RefreshCookie.Set(http,next.RawRefreshToken,next.Stored.ExpiresAt,app.Environment); return Results.Ok(next.Response);
}).AllowAnonymous().RequireRateLimiting("Auth");
auth.MapPost("/logout",async(HttpContext http,AppDbContext db,CancellationToken ct)=>{if(http.Request.Cookies.TryGetValue("refresh_token",out var raw)){var hash=TokenService.Hash(raw);var token=await db.RefreshTokens.SingleOrDefaultAsync(x=>x.TokenHash==hash,ct);if(token is not null){token.RevokedAt=DateTimeOffset.UtcNow;await db.SaveChangesAsync(ct);}}RefreshCookie.Delete(http,app.Environment);return Results.NoContent();}).AllowAnonymous();

MapCrud(app); InvoiceEndpoints.Map(app); EventEndpoints.Map(app); LogisticsEndpoints.Map(app); PurchasingEndpoints.Map(app); UserEndpoints.Map(app); SettingsEndpoints.Map(app); LoginActivityEndpoints.Map(app); SubscriptionEndpoints.Map(app); app.MapGet("/health",()=>Results.Ok(new{status="healthy"})); app.Run();

static void MapCrud(WebApplication app){
 var c=app.MapGroup("/api/customers").RequireAuthorization(); c.MapGet("/",async(AppDbContext db)=>Results.Ok(await db.Customers.OrderByDescending(x=>x.CreatedAt).Select(x=>new CustomerDto(x.Id,x.Name,x.Phone,x.Email,x.Address,x.CreatedAt)).ToListAsync())); c.MapGet("/{id:guid}",async(Guid id,AppDbContext db)=>await db.Customers.Where(x=>x.Id==id).Select(x=>new CustomerDto(x.Id,x.Name,x.Phone,x.Email,x.Address,x.CreatedAt)).SingleOrDefaultAsync() is {} x?Results.Ok(x):Results.NotFound()); c.MapPost("/",async(CustomerRequest r,AppDbContext db)=>{var x=new Customer{Name=r.Name,Phone=r.Phone,Email=r.Email,Address=r.Address};db.Add(x);await db.SaveChangesAsync();return Results.Created($"/api/customers/{x.Id}",new CustomerDto(x.Id,x.Name,x.Phone,x.Email,x.Address,x.CreatedAt));}); c.MapPut("/{id:guid}",async(Guid id,CustomerRequest r,AppDbContext db)=>{var x=await db.Customers.FindAsync(id);if(x is null)return Results.NotFound();x.Name=r.Name;x.Phone=r.Phone;x.Email=r.Email;x.Address=r.Address;await db.SaveChangesAsync();return Results.NoContent();}); c.MapDelete("/{id:guid}",async(Guid id,AppDbContext db)=>{var x=await db.Customers.FindAsync(id);if(x is null)return Results.NotFound();db.Remove(x);await db.SaveChangesAsync();return Results.NoContent();});
 var p=app.MapGroup("/api/products").RequireAuthorization(); p.MapGet("/",async(AppDbContext db)=>Results.Ok(await db.Products.OrderBy(x=>x.Name).Select(x=>new ProductDto(x.Id,x.Name,x.SKU,x.Description,x.SellingPrice,x.CostPrice,x.StockQuantity,x.IsActive,x.CreatedAt)).ToListAsync())); p.MapGet("/{id:guid}",async(Guid id,AppDbContext db)=>await db.Products.Where(x=>x.Id==id).Select(x=>new ProductDto(x.Id,x.Name,x.SKU,x.Description,x.SellingPrice,x.CostPrice,x.StockQuantity,x.IsActive,x.CreatedAt)).SingleOrDefaultAsync() is {} x?Results.Ok(x):Results.NotFound()); p.MapPost("/",async(ProductRequest r,AppDbContext db)=>{var x=new Product{Name=r.Name,SKU=r.SKU,Description=r.Description,SellingPrice=r.SellingPrice,CostPrice=r.CostPrice,StockQuantity=r.StockQuantity,IsActive=r.IsActive};db.Add(x);await db.SaveChangesAsync();return Results.Created($"/api/products/{x.Id}",new ProductDto(x.Id,x.Name,x.SKU,x.Description,x.SellingPrice,x.CostPrice,x.StockQuantity,x.IsActive,x.CreatedAt));}); p.MapPut("/{id:guid}",async(Guid id,ProductRequest r,AppDbContext db)=>{var x=await db.Products.FindAsync(id);if(x is null)return Results.NotFound();x.Name=r.Name;x.SKU=r.SKU;x.Description=r.Description;x.SellingPrice=r.SellingPrice;x.CostPrice=r.CostPrice;x.StockQuantity=r.StockQuantity;x.IsActive=r.IsActive;await db.SaveChangesAsync();return Results.NoContent();}); p.MapDelete("/{id:guid}",async(Guid id,AppDbContext db)=>{var x=await db.Products.FindAsync(id);if(x is null)return Results.NotFound();db.Remove(x);await db.SaveChangesAsync();return Results.NoContent();});
 var e=app.MapGroup("/api/expenses").RequireAuthorization(); e.MapGet("/",async(AppDbContext db)=>Results.Ok(await db.Expenses.OrderByDescending(x=>x.ExpenseDate).Select(x=>new ExpenseDto(x.Id,x.Description,x.Amount,x.ExpenseDate,x.Category,x.CreatedAt)).ToListAsync())); e.MapGet("/{id:guid}",async(Guid id,AppDbContext db)=>await db.Expenses.Where(x=>x.Id==id).Select(x=>new ExpenseDto(x.Id,x.Description,x.Amount,x.ExpenseDate,x.Category,x.CreatedAt)).SingleOrDefaultAsync() is {} x?Results.Ok(x):Results.NotFound()); e.MapPost("/",async(ExpenseRequest r,AppDbContext db)=>{var x=new Expense{Description=r.Description,Amount=r.Amount,ExpenseDate=r.ExpenseDate,Category=r.Category};db.Add(x);await db.SaveChangesAsync();return Results.Created($"/api/expenses/{x.Id}",new ExpenseDto(x.Id,x.Description,x.Amount,x.ExpenseDate,x.Category,x.CreatedAt));}); e.MapPut("/{id:guid}",async(Guid id,ExpenseRequest r,AppDbContext db)=>{var x=await db.Expenses.FindAsync(id);if(x is null)return Results.NotFound();x.Description=r.Description;x.Amount=r.Amount;x.ExpenseDate=r.ExpenseDate;x.Category=r.Category;await db.SaveChangesAsync();return Results.NoContent();}); e.MapDelete("/{id:guid}",async(Guid id,AppDbContext db)=>{var x=await db.Expenses.FindAsync(id);if(x is null)return Results.NotFound();db.Remove(x);await db.SaveChangesAsync();return Results.NoContent();});
}

public sealed class HttpTenantContext(IHttpContextAccessor accessor):ITenantContext { public bool IsAuthenticated=>accessor.HttpContext?.User.Identity?.IsAuthenticated==true; public Guid TenantId=>Guid.Parse(accessor.HttpContext!.User.FindFirstValue("tenant_id")!); public Guid UserId=>Guid.Parse(accessor.HttpContext!.User.FindFirstValue(ClaimTypes.NameIdentifier)!); }
public static class RefreshCookie { static CookieOptions Options(IHostEnvironment env)=>new(){HttpOnly=true,Secure=!env.IsDevelopment(),SameSite=SameSiteMode.Strict,Path="/api/auth",IsEssential=true}; public static void Set(HttpContext http,string token,DateTimeOffset expires,IHostEnvironment env){var options=Options(env);options.Expires=expires;http.Response.Cookies.Append("refresh_token",token,options);} public static void Delete(HttpContext http,IHostEnvironment env)=>http.Response.Cookies.Delete("refresh_token",Options(env)); }
public sealed class TokenService(IConfiguration config){ public (AuthResponse Response,RefreshToken Stored,string RawRefreshToken) Create(User u){var now=DateTimeOffset.UtcNow;var exp=now.AddMinutes(config.GetValue("Jwt:AccessMinutes",15));var claims=new[]{new Claim(JwtRegisteredClaimNames.Sub,u.Id.ToString()),new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim("tenant_id",u.TenantId.ToString()),new Claim(ClaimTypes.Role,u.Role),new Claim(JwtRegisteredClaimNames.Email,u.Email)};var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(config["Jwt:Key"]!));var jwt=new JwtSecurityToken(config["Jwt:Issuer"],config["Jwt:Audience"],claims,now.UtcDateTime,exp.UtcDateTime,new SigningCredentials(key,SecurityAlgorithms.HmacSha256));var raw=Convert.ToBase64String(RandomNumberGenerator.GetBytes(48));var stored=new RefreshToken{TenantId=u.TenantId,UserId=u.Id,TokenHash=Hash(raw),ExpiresAt=now.AddDays(config.GetValue("Jwt:RefreshDays",7))};return(new AuthResponse(new JwtSecurityTokenHandler().WriteToken(jwt),exp,new UserDto(u.Id,u.FirstName,u.LastName,u.Email,u.Role)),stored,raw);} public static string Hash(string value)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)));}
public sealed class ValidationFilter:IEndpointFilter { public async ValueTask<object?> InvokeAsync(EndpointFilterInvocationContext c,EndpointFilterDelegate next){var errors=new Dictionary<string,string[]>();foreach(var arg in c.Arguments.Where(x=>x is not null)){var results=new List<ValidationResult>();if(!Validator.TryValidateObject(arg!,new ValidationContext(arg!),results,true))foreach(var result in results)foreach(var member in result.MemberNames.DefaultIfEmpty("request"))errors[member]=[result.ErrorMessage??"Invalid value"];}return errors.Count>0?Results.ValidationProblem(errors):await next(c);}}
public sealed class SubscriptionAccessMiddleware(RequestDelegate next)
{
    public async Task InvokeAsync(HttpContext http,AppDbContext db,ITenantContext context)
    {
        if(!context.IsAuthenticated||HttpMethods.IsGet(http.Request.Method)||HttpMethods.IsHead(http.Request.Method)||HttpMethods.IsOptions(http.Request.Method)||Allowed(http.Request.Path)){await next(http);return;}
        var tenant=await db.Tenants.AsNoTracking().SingleAsync(x=>x.Id==context.TenantId,http.RequestAborted);var access=SubscriptionAccess.Evaluate(tenant,DateTimeOffset.UtcNow);
        if(access.IsReadOnly){http.Response.StatusCode=StatusCodes.Status402PaymentRequired;await http.Response.WriteAsJsonAsync(new{message=access.Message,code="subscription_read_only",accessEndsAt=access.AccessEndsAt},http.RequestAborted);return;}
        await next(http);
    }
    static bool Allowed(PathString path)=>path.StartsWithSegments("/api/auth")||path.StartsWithSegments("/api/subscription")||path.StartsWithSegments("/api/payments");
}
public static class SubscriptionAccess
{
    public static SubscriptionAccessDto Evaluate(Tenant tenant,DateTimeOffset now)
    {
        if(tenant.SubscriptionStatus==SubscriptionStatuses.Trialing&&tenant.TrialEndsAt>now)return new(tenant.SubscriptionStatus,false,$"Trial access ends on {tenant.TrialEndsAt:yyyy-MM-dd}.",tenant.TrialEndsAt);
        if(tenant.SubscriptionStatus==SubscriptionStatuses.Active&&(tenant.SubscriptionEndsAt is null||tenant.SubscriptionEndsAt>now))return new(tenant.SubscriptionStatus,false,"Subscription active.",tenant.SubscriptionEndsAt);
        if(tenant.SubscriptionStatus==SubscriptionStatuses.PastDue&&tenant.GraceEndsAt>now)return new(tenant.SubscriptionStatus,false,$"Payment is overdue. Update billing before {tenant.GraceEndsAt:yyyy-MM-dd}.",tenant.GraceEndsAt);
        if(tenant.SubscriptionStatus==SubscriptionStatuses.Cancelled&&tenant.SubscriptionEndsAt>now)return new(tenant.SubscriptionStatus,false,$"Subscription cancelled. Access continues until {tenant.SubscriptionEndsAt:yyyy-MM-dd}.",tenant.SubscriptionEndsAt);
        var message=tenant.SubscriptionStatus==SubscriptionStatuses.PastDue?"The payment grace period has ended. Business data is read-only until billing is resolved.":"Your subscription access has ended. Business data is read-only until a plan is activated.";
        return new(tenant.SubscriptionStatus,true,message,tenant.GraceEndsAt??tenant.SubscriptionEndsAt??tenant.TrialEndsAt);
    }
}
public partial class Program { }
